import Foundation

// SampleEventService — loads the bundled SampleEvent.json (generated by
// scripts/generate-sample-event.mjs) and hands back a fully-formed
// SeatingPlan with `isDemo = true`, plus a pre-baked SeatService.GenerateResult
// so the AI button can play it back without ever calling /api/seat.
//
// Demo plans are LOCAL ONLY. They never round-trip through Supabase. Every
// service that could leak cost (AI, image upload, share-link mint, save) must
// early-return on `plan.isDemo`. SampleEventService is the only place where
// the demo plan is materialized.
//
// The bundled JSON shape is documented in scripts/generate-sample-event.mjs.

final class SampleEventService {
    static let shared = SampleEventService()
    private init() {}

    /// Stable ID baked into the JSON. Anywhere in the app that needs to ask
    /// "is this the sample plan?" without dereferencing isDemo can compare
    /// against this constant — useful for early-return guards in services
    /// that take an `id: String` rather than a SeatingPlan.
    static let samplePlanId = "demo-sample-event"

    enum SampleError: LocalizedError {
        case bundleResourceMissing
        case decodeFailed(String)

        var errorDescription: String? {
            switch self {
            case .bundleResourceMissing: return "SampleEvent.json missing from app bundle"
            case .decodeFailed(let m):   return "Failed to decode SampleEvent.json: \(m)"
            }
        }
    }

    /// Cached on first load. Sample data is small (~250 KB) but parsing it
    /// every time the user toggles tabs is wasteful, and it never changes
    /// at runtime.
    private var cached: (plan: SeatingPlan, preBakedResult: SeatService.GenerateResult)?

    /// Returns the demo plan + the pre-baked AI playback result.
    func load() throws -> (plan: SeatingPlan, preBakedResult: SeatService.GenerateResult) {
        if let cached { return cached }

        guard let url = Bundle.main.url(forResource: "SampleEvent", withExtension: "json") else {
            throw SampleError.bundleResourceMissing
        }
        let data = try Data(contentsOf: url)

        let envelope: SampleEnvelope
        do {
            envelope = try JSONDecoder().decode(SampleEnvelope.self, from: data)
        } catch {
            throw SampleError.decodeFailed(error.localizedDescription)
        }

        let plan = envelope.toSeatingPlan()
        let preBakedResult = envelope.toGenerateResult()
        cached = (plan, preBakedResult)
        return (plan, preBakedResult)
    }

    /// Convenience: just the plan, hydrating fresh state every call so users
    /// can "reset" the demo by re-loading without restarting the app.
    func freshPlan() throws -> SeatingPlan {
        // Clear cache so reset is true reset.
        cached = nil
        let result = try load()
        return result.plan
    }

    /// Convenience: just the pre-baked AI result. Used by SeatService when
    /// the active plan is the demo and the user taps "AI seat".
    func preBakedResult() throws -> SeatService.GenerateResult {
        let result = try load()
        return result.preBakedResult
    }
}

// MARK: - Bundled JSON envelope

/// Top-level shape of SampleEvent.json. See scripts/generate-sample-event.mjs.
private struct SampleEnvelope: Decodable {
    let schemaVersion: Int
    let plan: SamplePlan
    let preBakedAI: SamplePreBakedAI

    func toSeatingPlan() -> SeatingPlan {
        plan.toDomain()
    }

    func toGenerateResult() -> SeatService.GenerateResult {
        preBakedAI.toGenerateResult()
    }
}

private struct SamplePlan: Decodable {
    let id: String
    let name: String
    let eventDate: String?
    let venue: String?
    let eventType: String
    let isDemo: Bool
    let roomWidth: Double?
    let roomHeight: Double?
    let roomShape: String?
    let measurementUnit: String?
    let hasSweetheartTable: Bool?
    let coupleType: String?
    let tables: [SampleTable]
    let guests: [SampleGuest]
    let rules: [SampleRule]
    let objects: [SampleObject]
    let categories: [[String: AnyJSONValue]]?
    let parties: [SampleParty]?

    func toDomain() -> SeatingPlan {
        let dateFormatter = DateFormatter()
        dateFormatter.dateFormat = "yyyy-MM-dd"
        let parsedDate = eventDate.flatMap { dateFormatter.date(from: $0) }

        return SeatingPlan(
            id: id,
            name: name,
            eventDate: parsedDate,
            venue: venue,
            eventType: SeatingPlan.EventType(rawValue: eventType) ?? .wedding,
            tables: tables.map { $0.toDomain() },
            guests: guests.map { $0.toDomain() },
            rules: rules.map { $0.toDomain() },
            objects: objects.map { $0.toDomain() },
            roomWidth: roomWidth,
            roomHeight: roomHeight,
            roomShape: roomShape,
            measurementUnit: measurementUnit,
            customRoomPoints: nil,
            roomFlipH: nil,
            roomFlipV: nil,
            roomZones: nil,
            hasSweetheartTable: hasSweetheartTable,
            includeMaybes: nil,
            coupleType: coupleType,
            createdAt: nil,
            updatedAt: nil,
            userId: nil,
            tier: "event_pass",  // demo plan is treated as event-pass-equivalent
            eventPassExpiresAt: Calendar.current.date(byAdding: .year, value: 10, to: Date()),
            eventPassPurchasedAt: nil,
            isDemo: isDemo,
            rawCategories: categories?.map { dict in
                dict.mapValues { AnyCodable($0.unwrapped) }
            },
            rawParties: parties?.map { p in
                [
                    "id":       AnyCodable(p.id),
                    "name":     AnyCodable(p.name),
                    "guestIds": AnyCodable(p.guestIds),
                ]
            },
            rawGroups: nil,
            rawFloorPlanImage: nil,
            rawFloorPlanOpacity: nil,
            rawSeatOrders: nil,
            rawGuestQR: nil
        )
    }
}

private struct SampleTable: Decodable {
    let id: String
    let name: String
    let type: String
    let seats: Int
    let x: Double
    let y: Double
    let width: Double?
    let height: Double?
    let diameter: Double?
    let sweetShape: String?
    let oneSide: Bool?
    let color: String?
    let assignments: [String: Int]?

    func toDomain() -> SeatTable {
        SeatTable(
            id: id,
            name: name,
            type: SeatTable.TableType(rawValue: type) ?? .round,
            seats: seats,
            x: x,
            y: y,
            rotation: nil,
            assignments: assignments ?? [:],
            locked: nil,
            color: color,
            width: width,
            height: height,
            diameter: diameter,
            sweetShape: sweetShape,
            oneSide: oneSide,
            notes: nil
        )
    }
}

private struct SampleGuest: Decodable {
    let id: String
    let firstName: String?
    let lastName: String?
    let name: String
    let display: String?
    let side: String
    let vip: Bool
    let rsvp: String
    let party: String?
    let meal: String?
    let categories: [String]?
    let dietaryTags: [String]?
    let plusOne: Bool?
    let isChild: Bool?
