    let isGroom: Bool?

    func toDomain() -> Guest {
        Guest(
            id: id,
            name: name,
            firstName: firstName,
            lastName: lastName,
            email: nil,
            categories: categories ?? [],
            dietary: nil,
            notes: nil,
            rsvp: Guest.RSVPStatus(rawValue: rsvp) ?? .yes,
            side: Guest.GuestSide(rawValue: side) ?? .none,
            vip: vip,
            accessibility: nil,
            plusOne: plusOne,
            party: party,
            display: display,
            dietaryTags: dietaryTags,
            highChair: nil,
            isChild: isChild,
            groupIds: nil,
            isBride: isBride,
            isGroom: isGroom,
            meal: meal,
            guestCreatedAt: nil
        )
    }
}

private struct SampleRule: Decodable {
    let id: String
    let type: String
    let guests: [String]
    let weight: Int
    let hard: Bool
    let enabled: Bool
    let desc: String?
    let partyId: String?

    func toDomain() -> SeatingRule {
        SeatingRule(
            id: id,
            type: SeatingRule.RuleType.parse(type),
            guests: guests,
            tableId: nil,
            weight: weight,
            hard: hard,
            enabled: enabled,
            categoryId: nil,
            objectId: nil,
            sideValue: nil,
            sideA: nil,
            sideB: nil,
            desc: desc,
            auto: nil,
            source: nil,
            partyId: partyId,
            groupId: nil
        )
    }
}

private struct SampleObject: Decodable {
    let id: String
    let type: String
    let name: String
    let x: Double
    let y: Double
    let width: Double
    let height: Double
    let color: String?
    let category: String?
    let isObstacle: Bool?

    func toDomain() -> RoomObject {
        RoomObject(
            id: id, type: type, name: name,
            x: x, y: y, width: width, height: height,
            rotation: nil, color: color, category: category, icon: nil,
            isObstacle: isObstacle, locked: nil
        )
    }
}

private struct SampleParty: Decodable {
    let id: String
    let name: String
    let guestIds: [String]
}

// MARK: - Pre-baked AI playback

private struct SamplePreBakedAI: Decodable {
    let assignments: [String: String]
    let seatOrders: [String: AnyJSONValue]?
    let score: Double?
    let scorecard: SampleScorecard?

    func toGenerateResult() -> SeatService.GenerateResult {
        // Round-trip through JSON so we can reuse SeatService.GenerateResult's
        // existing custom decoder (handles the score-int-or-double + nested
        // suggestions ambiguity already documented in SeatService).
        let unwrappedSeatOrders: Any = seatOrders.map { dict in
            dict.mapValues { $0.unwrapped }
        } ?? [:]
        let payload: [String: Any] = [
            "assignments": assignments,
            "seatOrders": unwrappedSeatOrders,
            "score": score ?? 100,
            "scorecard": scorecard?.encodedDictionary() ?? [:],
            "fallback": false,
        ]
        do {
            let data = try JSONSerialization.data(withJSONObject: payload, options: [])
            return try JSONDecoder().decode(SeatService.GenerateResult.self, from: data)
        } catch {
            // Fail loud rather than silently hand back an empty result —
            // a broken pre-bake is a build-time bug, not a runtime one,
            // and we want it surfaced immediately during dev.
            assertionFailure("SampleEvent preBakedAI decode failed: \(error)")
            return SeatService.GenerateResult.empty
        }
    }
}

private struct SampleScorecard: Decodable {
    let overallPercent: Double?
    let overallLabel: String?
    let totalRules: Int?
    let totalSatisfied: Int?

    func encodedDictionary() -> [String: Any] {
        var dict: [String: Any] = [:]
        if let v = overallPercent { dict["overallPercent"] = v }
        if let v = overallLabel { dict["overallLabel"] = v }
        if let v = totalRules { dict["totalRules"] = v }
        if let v = totalSatisfied { dict["totalSatisfied"] = v }
        // Empty rule buckets so SeatService's RuleBucket decoder doesn't choke
        dict["hardConstraints"] = ["total": 0, "satisfied": 0, "partial": 0, "violated": 0, "rules": []]
        dict["softPreferences"] = ["total": 0, "satisfied": 0, "partial": 0, "violated": 0, "rules": []]
        dict["suggestions"] = []
        return dict
    }
}

// MARK: - Lenient JSON value
//
// SampleEvent.json contains a few heterogeneous blobs (categories,
// seatOrders) where we don't want to type out the full schema for the
// demo. AnyJSONValue accepts whatever JSON throws at it and exposes
// the underlying value via `.unwrapped`.

private enum AnyJSONValue: Decodable {
    case string(String)
    case int(Int)
    case double(Double)
    case bool(Bool)
    case array([AnyJSONValue])
    case dictionary([String: AnyJSONValue])
    case null

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null }
        else if let v = try? c.decode(Bool.self) { self = .bool(v) }
        else if let v = try? c.decode(Int.self) { self = .int(v) }
        else if let v = try? c.decode(Double.self) { self = .double(v) }
        else if let v = try? c.decode(String.self) { self = .string(v) }
        else if let v = try? c.decode([AnyJSONValue].self) { self = .array(v) }
        else if let v = try? c.decode([String: AnyJSONValue].self) { self = .dictionary(v) }
        else { self = .null }
    }

    var unwrapped: Any {
        switch self {
        case .string(let s):     return s
        case .int(let i):        return i
        case .double(let d):     return d
        case .bool(let b):       return b
        case .array(let a):      return a.map { $0.unwrapped }
        case .dictionary(let d): return d.mapValues { $0.unwrapped }
        case .null:              return NSNull()
        }
    }
}

// MARK: - SeatService.GenerateResult convenience

extension SeatService.GenerateResult {
    /// Empty result used as a graceful fallback if pre-baked decode somehow
    /// fails. Tapping AI just returns no-op rather than crashing.
    static var empty: SeatService.GenerateResult {
        let json = """
        {"assignments":{},"seatOrders":{},"score":0,"fallback":false,
         "scorecard":{"overallPercent":0,"overallLabel":"N/A","totalRules":0,"totalSatisfied":0,
         "hardConstraints":{"total":0,"satisfied":0,"partial":0,"violated":0,"rules":[]},
         "softPreferences":{"total":0,"satisfied":0,"partial":0,"violated":0,"rules":[]},
         "suggestions":[]}}
        """.data(using: .utf8)!
        return (try? JSONDecoder().decode(SeatService.GenerateResult.self, from: json))
            ?? unsafeBitCast(0, to: SeatService.GenerateResult.self)  // unreachable
    }
}
